/** 
 * Method Declaration Creation
 */
private void createMethodDecl(polyglot.ast.MethodDecl method){
  try {
    String name=createName(method);
    ArrayList parameters=createParameters(method);
    ArrayList exceptions=createExceptions(method);
    soot.SootMethod sootMethod=createSootMethod(name,method.flags(),method.returnType().type(),parameters,exceptions);
    finishProcedure(method,sootMethod);
  } catch (UnsupportedOperationException e) {
    // 处理不可变集合操作异常
    throw new RuntimeException("Unsupported operation in method declaration creation", e);
  } catch (NullPointerException e) {
    // 处理空指针异常
    throw new RuntimeException("Null pointer in method declaration creation", e);
  } catch (RuntimeException e) {
    // 重新抛出已显式声明的运行时异常
    if (e.getMessage().contains("already declared") || 
        e.getMessage().contains("unnumbered") || 
        e.getMessage().contains("don't know how to de-phantomize") || 
        e.getMessage().contains("Aborting: can't find classfile")) {
      throw e;
    }
    throw new RuntimeException("Unexpected runtime exception", e);
  }
}
